package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.when;

public class ReaderBasedJsonParser_getTokenLocation_TriageGen1Test {

    private IOContext mockIoContext;
    private Object mockSource;

    @Before
    public void setUp() {
        mockIoContext = Mockito.mock(IOContext.class);
        mockSource = new Object();
        when(mockIoContext.getSourceReference()).thenReturn(mockSource);
    }

    /**
     * Helper method to instantiate ReaderBasedJsonParser using reflection 
     * because the constructor requires many internal dependencies.
     */
    private ReaderBasedJsonParser createParser(String json) throws Exception {
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                mockIoContext, 0, new StringReader(json), null, null);
        return parser;
    }

    /**
     * Helper to set private fields via reflection to control the state for testing.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsFieldName() throws Exception {
        // Arrange
        ReaderBasedJsonParser parser = createParser("{}");

        // Manually set the state to simulate being at a FIELD_NAME token
        setPrivateField(parser, "_currToken", JsonToken.FIELD_NAME);
        setPrivateField(parser, "_nameInputTotal", 100L);
        setPrivateField(parser, "_nameInputRow", 1);
        setPrivateField(parser, "_tokenInputCol", 5);

        // Act
        JsonLocation location = parser.getTokenLocation();

        // Assert
        assertNotNull(location);
        assertEquals(mockSource, location.getSourceRef());
        assertEquals(-1L, location.getByteOffset());
        assertEquals(100L, location.getByteOffset()); // Based on code: _nameInputTotal is passed as offset param? 
        // Looking at the provided code: new JsonLocation(src, -1L, _nameInputTotal, _nameInputRow, _tokenInputCol);
        // Note: The constructor signature for JsonLocation is typically (src, offset, row, col, context) 
        // or similar. Based on the provided snippet:
        // new JsonLocation(src, -1L, _nameInputTotal, _nameInputRow, _tokenInputCol);
        // We check the values mapped to the constructor positions.

        // Since we don't have the JsonLocation source code, we verify the logic path via values.
        // Path: if (_currToken == JsonToken.FIELD_NAME)
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsNotFieldName() throws Exception {
        // Arrange
        ReaderBasedJsonParser parser = createParser("{}");

        // Set state for a non-FIELD_NAME token (e.g., START_OBJECT)
        setPrivateField(parser, "_currToken", JsonToken.START_OBJECT);
        setPrivateField(parser, "_tokenInputTotal", 50L);
        setPrivateField(parser, "_tokenInputRow", 2);

        // We need to ensure getTokenColumnNr() works. It usually relies on _tokenInputCol.
        setPrivateField(parser, "_tokenInputCol", 3);

        // Act
        JsonLocation location = parser.getTokenLocation();

        // Assert
        assertNotNull(location);
        assertEquals(mockSource, location.getSourceRef());
        // Path: return new JsonLocation(src, 0L, _tokenInputTotal, _tokenInputRow, getTokenColumnNr());
    }

    @Test
    public void testGetTokenLocation_FieldBranchCoverage() throws Exception {
        // This test ensures we hit the 'else' branch by using a token that is not FIELD_NAME
        ReaderBasedJsonParser parser = createParser("{\"a\":1}");

        // Force token to be something else
        setPrivateField(parser, "_currToken", JsonToken.VALUE_STRING);
        setPrivateField(parser, "_tokenInputTotal", 10L);
        setPrivateField(parser, "_tokenInputRow", 1);
        setPrivateField(parser, "_tokenInputCol", 2);

        JsonLocation location = parser.getTokenLocation();

        // Verify the logic: offset should be 0L per the code provided
        // We can't easily check private fields of JsonLocation without reflection, 
        // but we validate the code executes the path.
        assertNotNull(location);
    }
}
